import logging
import random
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor
import time

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define a class for agents
class Agent:
    def __init__(self, name):
        self.name = name
        self.tasks = []

    def add_task(self, task):
        self.tasks.append(task)

# Define the hierarchical goal model
hierarchical_goals = {
    'Goal 1': {
        'Sub-Goal 1.1': {
            'Sub-Sub-Goal 1.1.1': 'Task 1',
            'Sub-Sub-Goal 1.1.2': 'Task 2'
        },
        'Sub-Goal 1.2': 'Task 3'
    },
    'Goal 2': {
        'Sub-Goal 2.1': 'Task 4',
        'Sub-Goal 2.2': {
            'Sub-Sub-Goal 2.2.1': 'Task 5',
            'Sub-Sub-Goal 2.2.2': 'Task 6'
        }
    },
    'Goal 3': {
        'Sub-Goal 3.1': 'Task 7',
        'Sub-Goal 3.2': 'Task 8'
    }
}

# Create 30 agents
agents = [Agent(f"Agent {i}") for i in range(30)]

# Function to assign tasks to an agent
def assign_tasks_to_agent(agent, hierarchical_goals):
    for goal in hierarchical_goals.values():
        if isinstance(goal, dict):
            for sub_goal in goal.values():
                if isinstance(sub_goal, str):
                    agent.add_task(sub_goal)
                elif isinstance(sub_goal, dict):
                    for sub_sub_goal in sub_goal.values():
                        if isinstance(sub_sub_goal, str):
                            agent.add_task(sub_sub_goal)
                        elif isinstance(sub_sub_goal, dict):
                            for sub_sub_sub_goal in sub_sub_goal.values():
                                if isinstance(sub_sub_sub_goal, str):
                                    agent.add_task(sub_sub_sub_goal)

# Function to detect and resolve conflicts
def detect_and_resolve_conflicts(agents):
    task_counts = defaultdict(int)
    for agent in agents:
        for task in agent.tasks:
            task_counts[task] += 1

    for agent in agents:
        new_tasks = []
        for task in agent.tasks:
            if task_counts[task] > 1:
                new_task = f"{task}_conflict_{random.randint(1, 100)}"
                logging.warning(f"Conflict detected for task {task}. Replacing with {new_task}")
                new_tasks.append(new_task)
            else:
                new_tasks.append(task)
        agent.tasks = new_tasks

# Use ThreadPoolExecutor for parallel processing
def assign_tasks_parallel(agents, hierarchical_goals):
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = [executor.submit(assign_tasks_to_agent, agent, hierarchical_goals) for agent in agents]
        for future in futures:
            future.result()

# Main function to assign tasks and resolve conflicts
def main():
    start_time = time.time()
    assign_tasks_parallel(agents, hierarchical_goals)
    detect_and_resolve_conflicts(agents)
    end_time = time.time()
    logging.info(f"Total processing time: {(end_time - start_time) * 1000:.2f} ms")

    # Print the tasks for each agent
    for agent in agents:
        logging.info(f"{agent.name} - Tasks: {agent.tasks}")

# Run the main function
if __name__ == "__main__":
    main()
```

