### Step 3: Implement the Goal Chart Logic

Here's an example of how you can implement the goal chart with dynamic transitions:

#### `GoalChart.js`

```javascript
import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';

const GoalChart = ({ data }) => {
  const svgRef = useRef();

  useEffect(() => {
    const svg = d3.select(svgRef.current);

    // Define scales
    const xScale = d3.scaleBand()
      .domain(data.map((_, i) => i))
      .range([0, 500])
      .padding(0.1);

    const yScale = d3.scaleLinear()
      .domain([0, d3.max(data)])
      .range([300, 0]);

    // Define axes
    const xAxis = d3.axisBottom(xScale);
    const yAxis = d3.axisLeft(yScale);

    // Append axes
    svg.append('g')
      .attr('transform', `translate(0,${300})`)
      .call(xAxis);

    svg.append('g')
      .call(yAxis);

    // Bind data and enter/update/exit pattern
    const bars = svg.selectAll('.bar')
      .data(data);

    bars.enter().append('rect')
      .attr('class', 'bar')
      .attr('x', (d, i) => xScale(i))
      .attr('y', d3.max(data))
      .attr('width', xScale.bandwidth())
      .attr('height', 0)
      .merge(bars)
      .transition()
      .duration(500)
      .attr('y', d => yScale(d))
