import React, { useState, useEffect } from 'react';
import mqtt from 'mqtt';

const mqttClient = mqtt.connect('ws://localhost:9001/mqtt');

const GoalSyncComponent = ({ agentIds }) => {
  const [goals, setGoals] = useState({});
  const [errors, setErrors] = useState([]);

  useEffect(() => {
    const subscribeToGoals = () => {
      agentIds.forEach(agentId => {
        mqttClient.subscribe(`/agent/${agentId}/goal`);
        mqttClient.on('message', (topic, message) => {
          const parsedMessage = JSON.parse(message.toString());
          setGoals(prevGoals => ({
            ...prevGoals,
            [parsedMessage.agentId]: parsedMessage.goal
          }));
        });
      });
    };

    const publishGoals = () => {
      agentIds.forEach(agentId => {
        mqttClient.publish(`/agent/${agentId}/goal`, JSON.stringify({ agentId, goal: 'new goal' }), { qos: 1 }, (err) => {
          if (err) {
            setErrors(prevErrors => [...prevErrors, { agentId, error: err }]);
            console.error(`Failed to publish goal for agent ${agentId}:`, err);
          }
        });
      });
    };

    subscribeToGoals();
    publishGoals();

    return () => {
      mqttClient.end();
    };
  }, [agentIds]);

  return (
    <div>
      <h1>Goal Sync Component</h1>
      <ul>
        {Object.keys(goals).map(agentId => (
