import gym
import json
import http.server
import socketserver
import threading

class CooperativeEnvironment(gym.Env):
    def __init__(self, num_agents):
        self.num_agents = num_agents
        self.agents = [Agent() for _ in range(num_agents)]

    def step(self, actions):
        # Calculate the reward based on the actions
        reward = 0
        for i, agent in enumerate(self.agents):
            if actions[i] == 1:
                agent.update_state("active")
                reward += 1
            else:
                agent.update_state("idle")

        # Return the new observation, reward, done, and info
        observation = [agent.state for agent in self.agents]
        done = False
        info = {}

        return observation, reward, done, info

    def update_visualization(self, states):
        # Send updated states to the visualization server
        with socketserver.TCPServer(("localhost", 8000), MyHandler) as httpd:
            httpd.serve_forever()

class Agent:
    def __init__(self):
        self.state = "idle"

    def update_state(self, new_state):
        self.state = new_state

class MyHandler(http.server.SimpleHTTPRequestHandler):
    def do_POST(self):
        content_length = int(self.headers['Content-Length'])
        post_data = self.rfile.read(content_length)
        states = json.loads(post_data.decode('utf-8'))
        self.send_response(200)
        self.end_headers()
        updateStates(states)

# Create a cooperative environment with 20 agents
