# Take a step in the environment
actions = [1] * 20  # Activate all agents
observation, reward, done, info = env.step(actions)

# Update visualization
states = [agent.state for agent in env.agents]
json_states = json.dumps(states)
http_request = f"POST / HTTP/1.1\r\nHost: localhost:8000\r\nContent-Length: {len(json_states)}\r\n\r\n{json_states}"
with socketserver.TCPServer(("localhost", 8000), MyHandler) as httpd:
    threading.Thread(target=httpd.serve_forever).start()
    sock = socketserver.socket.socket(socketserver.socket.AF_INET, socketserver.socket.SOCK_STREAM)
    sock.connect(("localhost", 8000))
    sock.sendall(http_request.encode())
    sock.close()

print(reward)
```

