            <h1>Goal Updater</h1>
            <ul>
                {goals.map((goal, index) => (
                    <li key={index}>
                        Agent {index}: {goal.value}
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default GoalUpdater;
```

