  beats {
    port => 5044
    ssl => true
    ssl_certificate => "/etc/logstash/certs/logstash.crt"
    ssl_key => "/etc/logstash/certs/logstash.key"
    ssl_cipher_suite => "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256,TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256,TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384,TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384"
    ssl_minimum_version => "TLSv1.2"
  }
}

filter {
  # Parse structured data using specific Grok patterns
  grok {
    match => { "message" => "%{TIMESTAMP_ISO8601:timestamp} %{LOGLEVEL:loglevel} \[%{DATA:thread}\] %{DATA:class} - %{GREEDYDATA:message}" }
  }

  # Handle parsing failures
  if "_grokparsefailure" in [tags] {
    mutate {
      add_tag => ["parsing_failure"]
    }
    drop { }
  }

  # Validate required fields
  if ![timestamp] or ![loglevel] or ![thread] or ![class] or ![message] {
    mutate {
      add_tag => ["validation_failure"]
    }
    drop { }
  }

  # Convert timestamp to proper date format
  date {
    match => [ "timestamp", "ISO8601" ]
    target => "@timestamp"
  }
}

output {
