    ssl_minimum_version => "TLSv1.2"
  }

  # Log errors to a separate file
  if "parsing_failure" in [tags] or "validation_failure" in [tags] {
    file {
      path => "/var/log/logstash/errors.log"
      codec => rubydebug
    }
  }
}
```

